import re

import pytest


def title_of(html: str) -> str:
    """Return the text between <title> and </title> in html, or "" if absent.

    The input is an already-fetched HTML string; this function must not
    perform any network access.
    """
    pattern = re.compile(
        r"<title(?:\s[^>]*)?>(.*?)</title\s*>",
        re.IGNORECASE | re.DOTALL,
    )
    match = pattern.search(html)
    if match is None:
        return ""
    body: str = match.group(1)
    return body


def test_simple_title() -> None:
    assert title_of("<html><head><title>Hello</title></head></html>") == "Hello"


def test_missing_title_returns_empty() -> None:
    assert title_of("<html><body>no head here</body></html>") == ""


def test_empty_input_returns_empty() -> None:
    assert title_of("") == ""


def test_uppercase_tags_are_matched() -> None:
    assert title_of("<HTML><TITLE>Shout</TITLE></HTML>") == "Shout"


def test_title_with_attributes() -> None:
    assert title_of('<title lang="en">Bonjour</title>') == "Bonjour"


def test_unclosed_title_returns_empty() -> None:
    assert title_of("<title>never closed") == ""


def test_first_title_wins() -> None:
    assert title_of("<title>one</title><title>two</title>") == "one"


@pytest.mark.parametrize(
    ("html", "expected"),
    [
        ("<title> spaced </title>", " spaced "),
        ("<title></title>", ""),
    ],
)
def test_whitespace_and_empty_content(html: str, expected: str) -> None:
    assert title_of(html) == expected
